import { useState } from "react";

export function BillingToggle({
  monthlyPrice = {{monthlyPrice}},
  annualPrice = {{annualPrice}},
  defaultAnnual = {{defaultAnnual}},
  accent = "{{accent}}",
  discountBadge = "{{discountBadge}}",
}) {
  const [annual, setAnnual] = useState(defaultAnnual);
  return (
    <div style={{ font: "16px system-ui, sans-serif", color: "#241430", display: "flex", flexWrap: "wrap", alignItems: "center", gap: 10 }}>
      <span>Monthly</span>
      <label style={{ position: "relative", display: "inline-block", width: 44, height: 24 }}>
        <input type="checkbox" checked={annual} onChange={() => setAnnual((a) => !a)} aria-label="Toggle annual billing"
          style={{ position: "absolute", opacity: 0, width: 44, height: 24, margin: 0, cursor: "pointer" }} />
        <span className="bt-track" style={{ position: "absolute", inset: 0, background: annual ? accent : "#24143033", borderRadius: 999 }}>
          <span className="bt-thumb" style={{ position: "absolute", top: 3, left: annual ? 23 : 3, width: 18, height: 18, borderRadius: "50%", background: "#FAF7F2" }} />
        </span>
      </label>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .bt-track { transition: background .15s; }
          .bt-thumb { transition: left .15s; }
        }
      `}</style>
      <span>Annual <span style={{ fontSize: 11, padding: "2px 6px", borderRadius: 999, color: "#FAF7F2", background: accent, marginLeft: 4 }}>{discountBadge}</span></span>
      <p style={{ flexBasis: "100%", margin: "8px 0 0", fontSize: 14, color: "#241430cc" }}>
        <strong>${monthlyPrice}</strong>/mo or <strong>${annualPrice}</strong>/yr
      </p>
    </div>
  );
}
